# frozen_string_literal: true

module Gcode
  # The slicer that wrote a G-code file, found from its top comments. Subclasses read the slicer's own comments (layer
  # changes) while Gcode::Analysis goes through the file.
  #
  #   Gcode::Slicer.detect(analysis) # => a Gcode::Slicer::PrusaSlicer, or nil when no slicer is recognised
  class Slicer
    COMMENT_PATTERNS = {
      'Cura' => /Generated with Cura_SteamEngine(.*)/,
      'PrusaSlicer' => /generated by PrusaSlicer(.*)/
    }.freeze

    def initialize(analysis)
      @analysis = analysis
    end

    def self.detect(analysis)
      analysis.top_file_comments.find do |comment|
        COMMENT_PATTERNS.find do |slicer, regex|
          return "::Gcode::Slicer::#{slicer}".constantize.new(analysis) if comment.match(regex)
        end
      end
    end

    def analyse_comment(comment, index)
      # Not implemented
    end
  end
end
